# Rule hypothesis: 3s that are diagonally adjacent (but NOT orthogonally) to a 2 become 1
def diagonal_neighbors(grid, H, W, r, c):
    for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < H and 0 <= nc < W:
            yield (nr, nc)

def orthogonal_neighbors(grid, H, W, r, c):
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < H and 0 <= nc < W:
            yield (nr, nc)
            if grid[r][c] == 2:  # We're only checking when a 2 is at (r,c)
                break
    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
        nr, nc = r+dr, c+dc
        if 0 <= nr < H and 0 <= nc < W:
            yield (nr, nc)

# First, find all 3s that are orthogonally adjacent to a 2 in Demo 2
orth_adj_3s = set()
for r in range(20):
    for c in range(20):
        if demo2_input[r][c] == 2:
            for (nr, nc) in orthogonal_neighbors(demo2_input, 20, 20, r, c):
                if demo2_input[nr][nc] == 3:
                    orth_adj_3s.add((nr, nc))

