def propagate_colors(grid):
    """For cells that are 0 or 2, propagate color from nearest non-0, non-2 cell."""
    h, w = len(grid), len(grid[0])
    output = [[0 for _ in range(w)] for _ in range(h)]

    # First pass: identify all colored regions
    # Then second pass: flood fill from colored cells to gray/empty cells

    colors = {}  # (r,c) -> color value

    # Initialize colors for non-0, non-2 cells
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and grid[r][c] != 2:
                colors[(r,c)] = grid[r][c]

    # BFS from each colored region
    def flood_color(start_color, start_cells):
        queue = list(start_cells)
        while queue:
            r, c = queue.pop(0)
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if (nr, nc) not in colors:
                        colors[(nr, nc)] = start_color
                        queue.append((nr, nc))

    # Handle each connected non-0, non-2 cell group separately
    visited_in_colors = set()
    for r in range(h):
        for c in range(w):
            if (r,c) in colors and (r,c) not in visited_in_colors:
                # Start from this cell - find its color and group
                color = colors[(r,c)]
                region = {(r,c)}
                queue = [(r,c)]
                while queue:
                    cr, cc = queue.pop(0)
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and (nr, nc) in colors:
                            if (nr, nc) not in region and colors[(nr, nc)] == color:
                                region.add((nr, nc))
                                queue.append((nr, nc))
                visited_in_colors.update(region)
                flood_color(color, region)

    # Now colors has values for all reachable cells
    # But we only want cells that were originally non-0
    for (r,c), color in colors.items():
        output[r][c] = color
        if (r,c) in colors:
            del colors[(r,c)]  # Clear as processed

    return output

